{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    alloc = [seg['minimum'] for seg in segments]
    caps = [seg['capacity'] for seg in segments]
    importance = [seg['importance'] for seg in segments]
    total = sum(alloc)
    if total > budget:
        # invalid – but assume valid input; fallback to cap at sum minima
        total = total
    while total < budget:
        best_idx = -1
        best_val = -1.0
        for i in range(n):
            if alloc[i] >= caps[i]:
                continue
            if alloc[i] + 1 > caps[i]:
                continue
            ratio = importance[i] / (alloc[i] + 1)
            if ratio > best_val:
                best_val = ratio
                best_idx = i
        if best_idx == -1:
            break   # cannot allocate more
        alloc[best_idx] += 1
        total += 1
    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    return {'allocations': alloc, 'by_name': by_name, 'total': total}"
}
